/* Stable exercise IDs are shared by the guide catalogue and workout prescriptions. */
const EXERCISE_GUIDES={
  riscaldamento_generale:{name:'Riscaldamento generale',group:'Mobilità',equipment:'Corpo libero',pose:'warmup',summary:'Prepara gradualmente il corpo alla sessione, senza cercare subito intensità.',captions:['Parti con un passo comodo','Muovi anche spalle e braccia'],steps:['Cammina o marcia sul posto a ritmo facile, muovendo le braccia.','Aggiungi circonduzioni lente delle spalle e piegamenti poco profondi delle ginocchia.','Aumenta il movimento con gradualità e passa alle serie preparatorie indicate dal preparatore.'],breathing:'Regolare e tranquilla, senza trattenere il fiato.',mistakes:['Partire subito con movimenti intensi o bruschi.','Forzare un movimento oltre il proprio controllo.'],cue:'Progressivo, fluido, senza fretta.',source:{name:'NHS · Riscaldamento',url:'https://www.nhs.uk/live-well/exercise/how-to-warm-up-before-exercising/'}},
  riscaldamento_anche_caviglie:{name:'Mobilità di anche e caviglie',group:'Mobilità',equipment:'Corpo libero · appoggio stabile',pose:'ankle',summary:'Una preparazione dolce per i movimenti della parte inferiore del corpo.',captions:['Tallone ben appoggiato','Ginocchio in avanti, senza forzare'],steps:['Dopo una breve marcia, assumi una posizione sfalsata vicino a un appoggio stabile.','Porta lentamente il ginocchio anteriore nella direzione delle dita del piede, mantenendo il tallone a terra; torna indietro e cambia lato.','Completa con movimenti controllati delle anche e piegamenti leggeri, secondo la sequenza del preparatore.'],breathing:'Respira liberamente durante tutti i movimenti.',mistakes:['Sollevare il tallone per aumentare l’ampiezza.','Rimbalzare o cercare un allungamento doloroso.'],cue:'Cerca mobilità, non il limite.',source:{name:'NHS · Preparazione al movimento',url:'https://www.nhs.uk/live-well/exercise/how-to-warm-up-before-exercising/'}},
  squat_bilanciere:{name:'Squat con bilanciere',group:'Gambe',equipment:'Bilanciere · rack',pose:'squat',summary:'Piega anche e ginocchia mantenendo il carico sotto controllo.',captions:['Appoggio stabile e busto attivo','Scendi con controllo, poi risali'],steps:['Sistema il bilanciere sulla parte alta del dorso secondo le indicazioni del preparatore. Trova un appoggio stabile con entrambi i piedi.','Piega anche e ginocchia insieme. Mantieni la schiena stabile e le ginocchia orientate come i piedi.','Scendi fino alla profondità che controlli, poi spingi il pavimento per tornare in piedi senza slanci.'],breathing:'Prepara il respiro prima della discesa e gestisci la risalita come concordato con il preparatore.',mistakes:['Perdere l’appoggio del piede o far cedere le ginocchia verso l’interno.','Inseguire la profondità perdendo la posizione della schiena.'],cue:'Piedi stabili, movimento controllato.',source:{name:'ACE · Movimento di squat',url:'https://www.acefitness.org/resources/everyone/exercise-library/135/bodyweight-squat/'}},
  panca_piana:{name:'Panca piana',group:'Parte superiore',equipment:'Panca · bilanciere',pose:'bench',summary:'Una spinta controllata con piedi e parte alta del dorso stabili.',captions:['Discesa controllata verso il petto','Spingi mantenendo gli appoggi'],steps:['Sdraiati sulla panca con i piedi appoggiati e le scapole stabili. Concorda presa, carico e assistenza con il preparatore.','Porta il bilanciere verso il petto con controllo, mantenendo i polsi allineati agli avambracci.','Spingi verso l’alto senza rimbalzi e senza perdere l’appoggio di piedi e dorso.'],breathing:'Inspira durante la discesa ed espira nella spinta, salvo istruzioni specifiche del preparatore.',mistakes:['Rimbalzare il bilanciere sul petto.','Piegare eccessivamente i polsi o perdere gli appoggi.'],cue:'Controlla il bilanciere in entrambe le direzioni.',source:{name:'NASM · Barbell bench press',url:'https://www.nasm.org/resource-center/exercise-library/barbell-bench-press'}},
  rematore_manubri:{name:'Rematore con manubri',group:'Parte superiore',equipment:'Due manubri',pose:'row',summary:'Tira i gomiti indietro mantenendo il busto fermo e la schiena stabile.',captions:['Busto inclinato, braccia distese','Gomiti indietro, senza slanci'],steps:['Con le ginocchia leggermente piegate, porta le anche indietro e inclina il busto mantenendo stabile la schiena. Lascia le braccia sotto le spalle.','Avvicina i manubri ai fianchi guidando il movimento con i gomiti, senza ruotare o sollevare il busto.','Riporta lentamente le braccia alla posizione iniziale mantenendo l’inclinazione.'],breathing:'Espira nella tirata e inspira mentre abbassi i manubri.',mistakes:['Dare uno slancio con il busto per sollevare il carico.','Alzare le spalle o incurvare la schiena.'],cue:'Muovi le braccia, mantieni fermo il busto.',source:{name:'ACE · Schema di tirata a busto inclinato',url:'https://www.acefitness.org/resources/everyone/exercise-library/12/bent-over-row/'}},
  affondi_alternati:{name:'Affondi alternati',group:'Gambe',equipment:'Corpo libero',pose:'lunge',summary:'Fai un passo e abbassa il corpo mantenendo equilibrio e controllo.',captions:['Parti in piedi, con equilibrio','Scendi tra i due appoggi'],steps:['Parti in piedi e fai un passo avanti abbastanza ampio da mantenere equilibrio.','Piega entrambe le ginocchia abbassando il corpo. Mantieni il piede anteriore appoggiato e il ginocchio orientato come le dita.','Spingi con la gamba anteriore per tornare alla partenza; ripeti con l’altra gamba.'],breathing:'Inspira mentre scendi, espira mentre risali.',mistakes:['Far cedere il ginocchio anteriore verso l’interno.','Perdere equilibrio o rimbalzare nella posizione bassa.'],cue:'Prima l’equilibrio, poi la profondità.',source:{name:'ACE · Forward lunge',url:'https://www.acefitness.org/resources/everyone/exercise-library/94/forward-lunge/'}},
  plank_frontale:{name:'Plank',group:'Core',equipment:'Tappetino',pose:'plank',summary:'Mantieni il corpo allineato mentre continui a respirare.',captions:['Gomiti sotto le spalle','Mantieni l’allineamento'],steps:['Appoggia gli avambracci a terra con i gomiti sotto le spalle. Distendi le gambe e appoggia le punte dei piedi.','Solleva il bacino fino a creare una linea tra testa, anche e caviglie. Attiva addome e glutei.','Mantieni la posizione per il tempo della scheda respirando regolarmente, poi riappoggiati con controllo.'],breathing:'Continua a respirare, senza irrigidirti trattenendo il fiato.',mistakes:['Lasciare scendere il bacino o sollevarlo troppo.','Spingere la testa in avanti o chiudere le spalle.'],cue:'Una linea lunga dalla testa ai talloni.',source:{name:'ACE · Front plank',url:'https://www.acefitness.org/resources/everyone/exercise-library/32/front-plank/'}},
  stacco_rumeno:{name:'Stacco rumeno',group:'Gambe',equipment:'Bilanciere',pose:'hinge',summary:'Il movimento parte dalle anche; il bilanciere rimane vicino alle gambe.',captions:['Bilanciere vicino alle cosce','Anche indietro, schiena stabile'],steps:['Parti in piedi con il bilanciere vicino alle cosce e le ginocchia leggermente piegate.','Porta le anche indietro mentre inclini il busto. Mantieni il bilanciere vicino alle gambe e la schiena stabile.','Fermati prima di perdere la posizione, poi estendi le anche per tornare in piedi senza inarcare la schiena.'],breathing:'Prepara il respiro prima di scendere e accompagna la risalita secondo le indicazioni del preparatore.',mistakes:['Piegare molto le ginocchia trasformando il movimento in uno squat.','Allontanare il bilanciere dal corpo o arrotondare la schiena.'],cue:'Porta le anche indietro, non il peso lontano.',source:{name:'NASM · Romanian deadlift',url:'https://www.nasm.org/resource-center/exercise-library/romanian-deadlift-barbell'}},
  split_squat:{name:'Split squat',group:'Gambe',equipment:'Corpo libero',pose:'split',summary:'Un affondo sul posto: i piedi restano fermi durante le ripetizioni.',captions:['Piedi sfalsati, tallone dietro sollevato','Scendi e risali sul posto'],steps:['Posiziona un piede avanti e uno dietro, con distanza sufficiente per mantenere equilibrio e il tallone posteriore sollevato.','Piega le ginocchia e scendi con controllo, mantenendo stabile il piede anteriore.','Risali senza spostare i piedi. Completa le ripetizioni previste e poi cambia lato.'],breathing:'Inspira in discesa ed espira in risalita.',mistakes:['Disporre i piedi su una linea troppo stretta e perdere equilibrio.','Far cedere il ginocchio anteriore verso l’interno.'],cue:'Gli appoggi restano fermi.',source:{name:'ACE · Principi del movimento in affondo',url:'https://www.acefitness.org/resources/everyone/exercise-library/94/forward-lunge/'}},
  leg_curl_prono:{name:'Leg curl',group:'Gambe',equipment:'Macchina leg curl da sdraiati',pose:'curl',summary:'Piega le ginocchia mantenendo il bacino appoggiato alla macchina.',captions:['Regola appoggi e rullo','Piega le ginocchia con controllo'],steps:['Regola la macchina con il preparatore: ginocchia allineate al perno e rullo appena sopra le caviglie. Sdraiati a pancia in giù.','Mantieni il bacino appoggiato e piega le ginocchia portando i talloni verso i glutei.','Riporta lentamente il rullo alla partenza, senza scatti. Questa guida mostra la variante da sdraiati.'],breathing:'Espira piegando le ginocchia e inspira durante il ritorno.',mistakes:['Sollevare il bacino o inarcare la schiena per aiutarsi.','Lasciare tornare il peso senza controllarlo.'],cue:'Si muovono le ginocchia, il bacino resta appoggiato.',source:{name:'NASM · Lying leg curl',url:'https://www.nasm.org/resource-center/exercise-library/lying-leg-curl'}},
  dead_bug:{name:'Dead bug',group:'Core',equipment:'Tappetino',pose:'deadbug',summary:'Muovi braccio e gamba opposti mantenendo stabile il tronco.',captions:['Braccia in alto, ginocchia piegate','Allunga braccio e gamba opposti'],steps:['Sdraiati sulla schiena con le braccia verso il soffitto e anche e ginocchia piegate. Attiva dolcemente l’addome.','Allunga lentamente un braccio dietro la testa e la gamba opposta, solo fin dove mantieni stabile il bacino e controlli la schiena.','Torna al centro e alterna i lati senza ruotare il busto.'],breathing:'Espira durante l’allungamento e inspira nel ritorno.',mistakes:['Inarcare la zona lombare quando allunghi gli arti.','Muovere velocemente o ruotare il bacino.'],cue:'Gli arti si muovono, il tronco resta stabile.',source:{name:'NASM · Dead bug',url:'https://www.nasm.org/workout-exercise-guidance/default?slug=dead-bug'}}
};
function guideForId(id){return Object.prototype.hasOwnProperty.call(EXERCISE_GUIDES,id)?EXERCISE_GUIDES[id]:null;}
function filterExerciseGuides(query=''){
 const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('it');
 const q=normalize(query).trim();return Object.entries(EXERCISE_GUIDES).filter(([id,g])=>normalize(g.name+' '+g.group+' '+g.equipment).includes(q));
}
let guideContext=null,guideLibraryQuery='',guideFromLibrary=false;
function guideDialog(){return document.getElementById('exercise-guide');}
function closeExerciseGuide(){guideDialog().close();}
function guideLibraryCard(){return `<section class="card guide-entry"><span class="guide-entry-icon" aria-hidden="true">i</span><div><h2>Ogni esercizio, spiegato bene.</h2><p class="small">Posizioni illustrate, esecuzione e consigli pratici. Tocca “i” nella scheda o esplora la guida.</p></div><button class="light" onclick="openGuideLibrary()">Esplora gli esercizi</button></section>`;}
function openGuideLibrary(){guideContext=null;guideFromLibrary=true;const d=guideDialog();d.innerHTML=`<header class="guide-header"><div><span class="eyebrow">MUOVITI CON CONSAPEVOLEZZA</span><h2 id="exercise-guide-title">Guida agli esercizi</h2></div><button class="close" aria-label="Chiudi guida" onclick="closeExerciseGuide()">×</button></header><div class="guide-body"><p class="small">Le spiegazioni degli esercizi presenti nelle tue schede, sempre a portata di mano.</p><label for="guide-search">Cerca per nome, attrezzatura o gruppo</label><input id="guide-search" type="search" placeholder="Es. plank, gambe, manubri…" value="${esc(guideLibraryQuery)}" oninput="guideLibraryQuery=this.value;renderGuideResults()"><p class="small guide-results-count" id="guide-results-count" role="status"></p><div id="guide-results" class="guide-library"></div></div>`;renderGuideResults();if(!d.open)d.showModal();d.scrollTop=0;d.querySelector('.close').focus({preventScroll:true});}
function renderGuideResults(){const results=filterExerciseGuides(guideLibraryQuery);$('#guide-results-count').textContent=results.length+(results.length===1?' esercizio':' esercizi');$('#guide-results').innerHTML=results.length?results.map(([id,g])=>`<button class="guide-library-item" onclick="openExerciseGuide('${id}')"><span class="guide-thumb" aria-hidden="true">${exerciseFigure(g.pose,1,true)}</span><span><span class="badge">${g.group}</span><strong>${g.name}</strong><span class="small">${g.equipment}</span></span><span class="guide-chevron" aria-hidden="true">›</span></button>`).join(''):'<div class="guide-no-results"><h3>Nessun esercizio trovato</h3><p class="small">Prova un altro nome oppure cerca “core”, “gambe” o “mobilità”.</p></div>';}
function openExerciseGuide(id,letter=null,index=null){
 const g=guideForId(id),d=guideDialog();guideContext=letter!==null?{letter,index}:null;guideFromLibrary=letter===null;
 if(!g){d.innerHTML=`<header class="guide-header"><h2 id="exercise-guide-title">Guida non disponibile</h2><button class="close" aria-label="Chiudi guida" onclick="closeExerciseGuide()">×</button></header><div class="guide-body"><p>Questo esercizio non è ancora presente nella libreria. Consulta le indicazioni del tuo preparatore.</p></div>`;if(!d.open)d.showModal();return;}
 const ex=guideContext?exercisePlans[letter]?.[index]:null;
 d.innerHTML=`<header class="guide-header"><div><span class="eyebrow">GUIDA ALL’ESECUZIONE</span><h2 id="exercise-guide-title">${g.name}</h2></div><button class="close" aria-label="Chiudi guida" onclick="closeExerciseGuide()">×</button></header><div class="guide-body"><div class="guide-meta"><span class="badge">${g.group}</span><span class="small">${g.equipment}</span></div><p class="guide-summary">${g.summary}</p><div class="guide-visuals">${g.captions.map((caption,i)=>`<figure><div class="guide-visual">${exerciseFigure(g.pose,i,false,g.name+' — '+caption)}</div><figcaption><span>${i+1}</span>${caption}</figcaption></figure>`).join('')}</div><p class="guide-image-note small">Illustrazioni schematiche · Leggi anche i passaggi qui sotto.</p>${ex?`<section class="guide-prescription"><span class="eyebrow">NELLA TUA SCHEDA</span><strong>${ex.detail}</strong><p class="small">Questi sono i tempi previsti per questa sessione.</p></section>`:''}<section class="guide-section"><h3>Come eseguirlo</h3><ol class="guide-steps">${g.steps.map(step=>`<li>${step}</li>`).join('')}</ol></section><section class="guide-breath"><span aria-hidden="true">↔</span><div><h3>Respirazione</h3><p>${g.breathing}</p></div></section><section class="guide-section"><h3>Errori da evitare</h3><ul class="guide-mistakes">${g.mistakes.map(m=>`<li>${m}</li>`).join('')}</ul></section><div class="guide-cue"><span class="eyebrow">DA RICORDARE</span><p>${g.cue}</p></div><p class="small guide-personal">Segui le varianti e le indicazioni personali del tuo preparatore. La guida descrive l’esecuzione generale.</p><details class="guide-source"><summary>Riferimento tecnico</summary><a href="${g.source.url}" target="_blank" rel="noopener noreferrer">${g.source.name} ↗</a></details><button class="guide-return" onclick="${guideFromLibrary?'openGuideLibrary()':'closeExerciseGuide()'}">${guideFromLibrary?'Torna alla guida':'Torna alla scheda'}</button></div>`;
 if(!d.open)d.showModal();d.scrollTop=0;d.querySelector('.close').focus({preventScroll:true});
}
